# -*- coding: utf-8 -*-
# 多选题：PART 02 膳食纤维平衡 / 水平衡 / 七大营养素平衡小结，出处：ycnc_paras.txt（你是你吃出来的·上册）
mq3 = [
{"q":"关于膳食纤维，正确的有？","o":["多年前人们认为它是食物中最“没营养”的成分","随着营养学的发展，人们越来越重视膳食纤维在平衡膳食中的作用","蔬菜里的维生素、矿物质和水在肠道被吸收后，余下的就是膳食纤维","膳食纤维在小肠中被人体直接吸收利用"],"a":[0,1,2],"e":"很多年前，人们对膳食纤维的认识还有偏颇，认为它是食物中最“没营养”的成分。这些年随着营养学的发展，人们越来越重视膳食纤维在平衡膳食中的作用。蔬菜里的维生素、矿物质和水在肠道被吸收，进入血液，余下的是什么？是膳食纤维。它穿过小肠，来到了大肠。"},
{"q":"关于可溶性膳食纤维，正确的有？","o":["在肠道中能够被细菌发酵分解","是肠道细菌的食物，可促进细菌的繁殖，增加粪便中的细菌数量","包括胶质、树脂、菊粉、低聚糖等","主要存在于水果、蔬菜、海带、紫菜及豆类中","主要存在于粗粮和豆类种子的外皮中"],"a":[0,1,2,3],"e":"在肠道中能够被细菌发酵分解的膳食纤维称为可溶性膳食纤维，它们是肠道细菌的食物，可促进细菌的繁殖，增加粪便中的细菌数量。这种可溶性膳食纤维包括胶质、树脂、菊粉、低聚糖等，主要存在于水果、蔬菜、海带、紫菜及豆类中。"},
{"q":"关于非可溶性膳食纤维，正确的有？","o":["不易被细菌发酵，穿肠而过","可以促进肠蠕动，加速粪便的排泄","包括纤维素、半纤维素、木质素、抗性淀粉等","主要存在于粗粮、豆类种子的外皮、植物的茎和叶中","主要存在于水果的果肉中"],"a":[0,1,2,3],"e":"还有一类膳食纤维不能被细菌发酵，穿肠而过，可以促进肠蠕动，加速粪便的排泄。它不易被细菌发酵，包括纤维素、半纤维素、木质素、抗性淀粉等，主要存在于粗粮、豆类种子的外皮、植物的茎和叶中。"},
{"q":"膳食纤维的四大功能包括？","o":["有利于通便","有利于减肥","有利于预防结肠癌","有利于降低餐后血糖","有利于提高食物的能量密度"],"a":[0,1,2,3],"e":"膳食纤维的四大功能说起来，会让很多人眼前一亮……第一，有利于通便。第二，有利于减肥。第三，有利于预防结肠癌。第四，有利于降低餐后血糖。"},
{"q":"膳食纤维为什么有利于预防结肠癌？","o":["益生菌的增加具有保护肠道黏膜和滋养结肠的功效","可以抑制致病菌对结肠黏膜的伤害","当结肠细菌得不到可溶性膳食纤维时，会造成益生菌减少，结肠癌的发生率增加","膳食纤维能直接杀死结肠癌细胞"],"a":[0,1,2],"e":"第三，有利于预防结肠癌。益生菌的增加具有保护肠道黏膜和滋养结肠的功效，并且可以抑制致病菌对结肠黏膜的伤害。当结肠细菌得不到可溶性膳食纤维时，会造成益生菌减少，结肠癌的发生率增加。"},
{"q":"为什么糖尿病人要多吃蔬菜、薯类这些含膳食纤维多的食物？","o":["膳食纤维会减缓食物的吸收速度","有利于减缓血糖上升的速度","膳食纤维能直接分解血糖","膳食纤维能刺激胰岛素分泌"],"a":[0,1],"e":"第四，有利于降低餐后血糖。膳食纤维会减缓食物的吸收速度，因此有利于减缓血糖上升的速度，所以糖尿病人要多吃一些蔬菜、薯类这些含膳食纤维多的食物。"},
{"q":"膳食纤维摄入过多会怎样？","o":["主要出现在减肥人群中，因为食用这样的食物可以增加饱腹感","长期这样会造成身体中其他重要营养素的缺乏","容易造成营养不良，严重者会因为缺乏人体必需的营养素而生病","会让人迅速发胖"],"a":[0,1,2],"e":"摄入过多主要出现在减肥人群中……许多人通过多摄入膳食纤维的方法瘦身，吃蔬菜和水果再加上各种膳食纤维。的确，这样很快就会瘦下去，但是长期这样会造成身体中其他重要营养素的缺乏。也就是说，如果只想着给细菌吃饭，却忽略了自己身体细胞的需求，容易造成营养不良，严重者会因为缺乏人体必需的营养素而生病。"},
{"q":"现在人们容易出现膳食纤维缺乏的饮食原因包括？","o":["吃细粮较多，肉类较以前也增加许多","粮食类只选择米饭、馒头，或者面包、面条","吃菜少","吃水果时还削皮","每天吃大量粗粮"],"a":[0,1,2,3],"e":"现在人们吃细粮较多，肉类较以前也增加许多。一些人的日常饮食中粮食类只选择米饭、馒头，或者面包、面条，吃菜少，吃水果时还削皮，大大减少了对膳食纤维的摄入，非常容易出现腹胀，肥胖，血糖高，大便干，或者大便黏的症状。"},
{"q":"膳食纤维缺乏容易出现的症状包括？","o":["腹胀","肥胖、血糖高","大便干，或者大便黏","夜盲症"],"a":[0,1,2],"e":"非常容易出现腹胀，肥胖，血糖高，大便干，或者大便黏的症状。"},
{"q":"那位32岁男性患者（120千克）的情况包括？","o":["血糖高，一直在打胰岛素","食欲极好，特别喜欢追求口味","偏爱吃各种粮食类食物，米饭一天能吃500克","把土豆、黄瓜和西红柿当作蔬菜","大便4～5天一次，需要经常使用各种排便的药","他平时喝酒吸烟很多"],"a":[0,1,2,3,4],"e":"我曾经接诊过一位患者，男性，32岁，体重为120千克。他血糖高，一直在打胰岛素。……他不喝酒，不吸烟，日常工作中体力活动不多，在家里又没有特意去锻炼。但是他的食欲极好，特别喜欢追求口味……他偏爱吃各种粮食类食物，比如米饭一天能吃500克（1斤）。问及蔬菜，他说他可爱吃蔬菜了，比如土豆、黄瓜和西红柿……他说：“大便这件事对我来说太难，太痛苦。如果不用药，4～5天一次，所以我经常使用各种排便的药。”"},
{"q":"关于膳食纤维的建议摄入量与实际摄入量，正确的有？","o":["《中国居民膳食指南（2016）》要求中国成年人每天应摄入膳食纤维25～35克","目前中国人平均摄入量仅为13.3克，存在严重不足","美国人平均每人每天膳食纤维摄入量只有4～6克，所以美国人结肠癌的发生率很高","中国人的膳食纤维摄入量已远超标准"],"a":[0,1,2],"e":"《中国居民膳食指南（2016）》要求中国成年人每天应摄入膳食纤维25～35克，而目前中国人平均摄入量仅为13.3克，存在严重不足，而且这种情况越来越紧迫。美国人在这方面问题更严重，平均每人每天膳食纤维摄入量只有4～6克，所以美国人结肠癌的发生率很高。"},
{"q":"膳食纤维主要存在于哪里？","o":["主要存在于蔬菜、水果中","精米、精面中很少","肉、鱼、奶中没有","主要存在于肉、鱼、奶中"],"a":[0,1,2],"e":"膳食纤维主要存在于蔬菜、水果中，精米、精面中很少，肉、鱼、奶中没有。"},
{"q":"关于不同蔬菜的膳食纤维含量，正确的有？","o":["瓜类、茎类蔬菜含水量高，膳食纤维含量并不高","100克西红柿中膳食纤维只有0.5克","大家还是尽量选择叶菜类和菇类蔬菜","紫菜、海带的膳食纤维是在晒干状态下计算的，水泡发之后含量会大打折扣","西红柿的膳食纤维含量在所有蔬菜中最高"],"a":[0,1,2,3],"e":"蔬菜中膳食纤维的计算方式是指100克新鲜蔬菜里的膳食纤维含量。其中，瓜类、茎类蔬菜含水量高，膳食纤维含量并不高，100克西红柿中膳食纤维只有0.5克……因此大家还是尽量选择叶菜类和菇类蔬菜。有一些属于蔬菜但不是新鲜蔬菜的菜类，比如紫菜、海带，计算膳食纤维的时候是在晒干的状态下去计算的，经过水泡发之后，含量也会大打折扣。"},
{"q":"作者对蔬菜水果摄入的具体建议有？","o":["每个人一天最好吃1斤蔬菜，其中叶菜最好占一半","水果最好是连皮吃，这样膳食纤维可以多吃一些","主食应选择全谷类、薯类、根茎类食物","少吃精米、精面和精面加工制品，比如面包、蛋糕、饼干等","水果最好削皮吃"],"a":[0,1,2,3],"e":"所以，我们每个人一天最好吃1斤蔬菜，其中叶菜最好占一半。水果最好是连皮吃，这样膳食纤维可以多吃一些。主食应选择全谷类、薯类、根茎类食物，少吃精米、精面和精面加工制品，比如面包、蛋糕、饼干等。"},
{"q":"作者在门诊调查中发现的膳食纤维摄入情况有？","o":["十有八九的人膳食纤维不足","吃蔬菜每天250克以上的人不到一半","大概有一半人做不到每天吃水果","就这一半吃水果的人，大部分还把水果皮削了","所有人都能保证每天吃够蔬菜和水果"],"a":[0,1,2,3],"e":"我在门诊做了些调查，十有八九的人膳食纤维不足，吃蔬菜每天250克以上的人不到一半，大概有一半人做不到每天吃水果，就这一半吃水果的人，大部分还把水果皮削了。"},
{"q":"关于水在人体内的作用，正确的有？","o":["人的身体中60%左右都是水","细胞的新陈代谢、微循环中的物质交换都是在水溶液中进行的","水可以调节体温，运送营养和氧气，排出废物和毒素","水可以润滑和保护组织器官","水是三大产能营养素之一"],"a":[0,1,2,3],"e":"人的身体中60%左右都是水，细胞的新陈代谢、微循环中的物质交换都是在水溶液中进行的。在人体内，水还可以调节体温，运送营养和氧气，排出废物和毒素，润滑和保护组织器官。"},
{"q":"人体每日摄水量约2500毫升，其来源包括？","o":["饮水，包括白开水、矿泉水、饮料、茶水，大概有1200毫升","食物，比如萝卜、西红柿、米饭、汤、粥，大约有1000毫升","物质代谢，葡萄糖在线粒体内产生能量的同时会产生水，大约为300毫升","呼吸吸入的水，约500毫升"],"a":[0,1,2],"e":"一个人每日的摄水量总和约为2500毫升，来源有3个：第一，饮水。包括各种各样的水，比如白开水、矿泉水、饮料、茶水，大概有1200毫升。第二，食物……大约有1000毫升。第三，物质代谢。葡萄糖在线粒体内产生能量的同时会产生水，这些水可以被人体再利用，大约为300毫升。"},
{"q":"在标准室温20℃左右，水的输出渠道包括？","o":["肾脏，以尿液的形式排出，一天一般是1500毫升左右","呼吸，每天大约350毫升","皮肤，一般一天会通过皮肤蒸发掉500毫升水分","大便，每天排出150毫升水分","头发和指甲，每天约200毫升"],"a":[0,1,2,3],"e":"在标准室温20℃左右，水的输出总和同样约为2500毫升，渠道有4个：第一，肾脏……一天一般是1500毫升左右。第二，呼吸……每天大约350毫升。第三，皮肤……一天会通过皮肤蒸发掉500毫升水分。第四，大便。人每天通过大便排出150毫升水分。"},
{"q":"关于人体缺水程度与表现，正确的有？","o":["缺水量达到体重的2%时，会感到口渴","到10%时，会烦躁无力，体温升高，血压下降","达到20%就会有生命危险","缺水量达到1%就会有生命危险"],"a":[0,1,2],"e":"当人体中缺水量达到人体体重的2%时，会感到口渴；到10%时，会烦躁无力，体温升高，血压下降；达到20%就会有生命危险。"},
{"q":"哪些人要注意水是否摄入过多？","o":["肾功能不全的人","心功能不好的人","体内水多了会加重心、肾的负担","运动中出汗多的人"],"a":[0,1,2],"e":"只有在某些特殊疾病情况下，才要注意水的摄入。比如肾功能不全的人、心功能不好的人要注意水是否摄入过多，因为体内水多了会加重心、肾的负担；而脑缺血、运动中出汗多的人，要注意水是否摄入过少，因为他们正是最需要水的人群。"},
{"q":"哪两类人正是最需要水的？","o":["脑缺血的人","运动中出汗多的人","肾功能不全的人","心功能不好的人"],"a":[0,1],"e":"而脑缺血、运动中出汗多的人，要注意水是否摄入过少，因为他们正是最需要水的人群。"},
{"q":"那位50多岁男性突发脑血栓的经过包括？","o":["7月去南方出差，和同事一起爬山，出了很多汗","虽然已经很渴，但依然不肯停下来喝水","在离山顶还有300米时，左腿无力，紧接着左胳膊也抬不起来","一检查是脑血栓","他是在家里休息时突然发病的"],"a":[0,1,2,3],"e":"有一年7月，他去南方出差，和几位同事一起爬山。争强好胜的他不肯落后，出了很多汗，气喘吁吁，仍然保持在队伍的前列。当时为了赶时间，他虽然已经很渴，但依然不肯停下来喝水……可就在离山顶还有300米的时候，他的左腿开始变得无力，紧接着左胳膊也抬不起来了……一检查是脑血栓。"},
{"q":"这位50多岁男性发生脑血栓的机制包括？","o":["气温高、运动量大、出汗多，造成血容量不足","血管内压力比较低，人体最高处处于缺血状态","右侧大脑中动脉与前动脉分布区的交界处（额顶部皮层）有明显的缺血灶","他本身有严重的高血压和糖尿病"],"a":[0,1,2],"e":"这个部位是全身最高处，也就是说当时由于气温高、运动量大、出汗多，造成了他血容量不足，血管内压力比较低，人体最高处处于缺血状态。后来我看了他的CT和核磁片子，在右侧大脑中动脉与前动脉分布区的交界处（额顶部皮层）有个明显的缺血灶。……平时身体还好，血压正常，血糖正常。"},
{"q":"关于血液与缺水，正确的有？","o":["一个正常人血管里的血液大概有5升左右","其中将近一半是红细胞、白细胞、血小板，剩下的是血浆","血浆中90%是水","缺水时血浆总量首先会减少，从而引起血容量减少和血液黏度增加","缺水会使血液黏度降低"],"a":[0,1,2,3],"e":"一个正常人血管里的血液大概有5升左右，其中将近一半是红细胞、白细胞、血小板，剩下的是血浆。血浆中90%是水，如果缺水，血浆总量首先会减少，从而引起血容量减少和血液黏度增加。"},
{"q":"为什么大脑的两个血管交界区容易发生缺血？","o":["是两个大血管之间的小血管集中部位","人运动时血管中液体量少，压力达不到顶部","血液黏度高","该部位血管特别粗大"],"a":[0,1,2],"e":"人运动时，如果血管中液体量少，压力达不到顶部，黏度又高，大脑的两个血管交界区是两个大血管之间的小血管集中部位，就很容易发生缺血。"},
{"q":"作者对那位脑血栓患者的建议是？","o":["病因很清楚，只是缺水","以后不再出现类似缺水的情况就可以了","注意补水，补营养，经常运动","需要长期服用活血药"],"a":[0,1,2],"e":"我告诉他，病因很清楚，只是缺水，以后不再出现类似缺水的情况就可以了。注意补水，补营养，经常运动，他就不会出现类似的症状。"},
{"q":"关于正常人的饮水量，正确的有？","o":["正常情况下，普通人每天应该饮水1200～1500毫升","天热时要注意多喝水","排汗多或者运动较多的人也要多喝水","中国人喜欢喝粥、喝汤、吃热汤面，单纯从饮水中获得的水可以相应减少","所有人都必须每天喝8杯水"],"a":[0,1,2,3],"e":"正常情况下，普通人每天应该饮水1200～1500毫升，但是天热时要注意多喝水，排汗多或者运动较多的人也要多喝水。中国人喜欢喝粥、喝汤、吃热汤面，这样能在饮食中摄入较多的水分，那么单纯从饮水中获得的水可以相应减少。"},
{"q":"判断饮水量是否合适，主要观察哪两项指标？","o":["看自己渴不渴","观察尿液的颜色和排尿量","体重变化","血压高低"],"a":[0,1],"e":"怎么判断自己一天的饮水量是否合适呢？主要观察两项指标：一个是看自己渴不渴……另一个是观察尿液的颜色和排尿量。"},
{"q":"关于口渴与饮水，正确的有？","o":["渴了才喝水是不对的","饮水量合适的情况下，人是不应该感觉口渴的","口渴说明身体正常","口渴时应立即大量饮水"],"a":[0,1],"e":"一个是看自己渴不渴，渴了才喝水是不对的。饮水量合适的情况下，人是不应该感觉口渴的。"},
{"q":"关于正常尿液，正确的有？","o":["正常情况下尿液是淡黄色的","一天的排尿量是1500毫升左右","一般3～4小时排尿一次","如果半天不想上厕所，或者排出的尿液是深黄色的，说明饮水量不足","尿液像水一样清说明喝水过多","正常的排尿频率是每10分钟一次"],"a":[0,1,2,3,4],"e":"另一个是观察尿液的颜色和排尿量。正常情况下尿液是淡黄色的，一天的排尿量是1500毫升左右，一般3～4小时排尿一次。如果半天不想上厕所，或者排出的尿液是深黄色的，那就说明饮水量不足了；反之，如果频频如厕，且尿液像水一样清，那就喝得有些过多了。"},
{"q":"关于每天喝多少水的结论，正确的有？","o":["到底是8杯水还是12杯水，这是因人而异的","没有放之四海而皆准的数量","作者的回答是看自己的口渴感觉，看自己尿的颜色和排尿频率","必须严格每天8杯水"],"a":[0,1,2],"e":"可是到底是8杯水还是12杯水，这是因人而异的，没有放之四海而皆准的数量。我的回答很简单：看自己的口渴感觉，看自己尿的颜色和排尿频率。"},
{"q":"人类每一天身体的输出（按基因赋予的任务执行）包括？","o":["能量输出","新陈代谢","修复自身结构","免疫防卫","主动增殖器官"],"a":[0,1,2,3],"e":"人类每一天身体的输出都是按照基因赋予我们的任务去执行，包括四个方面：能量输出、新陈代谢、修复自身结构和免疫防卫。"},
{"q":"关于吸烟与抗氧化剂，正确的有？","o":["吸烟的人身体中自由基过多，要多补充抗氧化剂去对抗自由基","最常见的抗氧化剂是维生素A、C、E","吸烟的人摄入维生素A、C、E要比一般人多一些","很多吸烟的人特别不喜欢吃水果，对身体的伤害大，得病的概率就高","吸烟的人应减少维生素A、C、E的摄入"],"a":[0,1,2,3],"e":"也有一些需要额外消耗的事情，比如吸烟的人身体中自由基过多，要多补充抗氧化剂去对抗自由基。最常见的抗氧化剂是维生素A、C、E，所以吸烟的人摄入维生素A、C、E要比一般人多一些。但是我们往往看到很多吸烟的人特别不喜欢吃水果，于是，身体内自由基多，对身体的伤害大，得病的概率就高。"},
{"q":"关于生命原料的输入与睡眠，正确的有？","o":["一个人每天的生命原料输入只有一个渠道，就是吃","通过每一餐摄取大自然的营养素来满足自己身体输出的需求","睡眠是让身体放松，给自身身体一个用营养素来修复的时间","睡眠也是营养素的一个输入渠道"],"a":[0,1,2],"e":"一个人每天的生命原料输入只有一个渠道，就是吃，通过每一餐摄取大自然的营养素来满足自己身体输出的需求。睡眠是让身体放松，给自身身体一个用营养素来修复的时间。"},
{"q":"关于身体状况的高平衡与低平衡，正确的有？","o":["运动多，思考多，饮食不挑嘴，荤素通吃，能保持标准体重和旺盛精力，这叫高平衡","不爱运动，也不爱动脑子，每样都吃一点，也是荤素通吃，体重正常，化验正常，但动作总像慢半拍，这叫低平衡","高平衡与低平衡都属于身体状况平衡","低平衡比高平衡更理想","低平衡属于不平衡"],"a":[0,1,2],"e":"人的身体状况平衡可分为两种：高平衡和低平衡。运动多，思考多，饮食不挑嘴，荤素通吃，能够保持标准的体重和旺盛的工作精力，这叫高平衡。不爱运动，也不爱动脑子，吃饭时每样都吃一点，也是荤素通吃，体重正常，化验正常，但是这个人的动作总像是慢半拍，有点与世无争的样子，这叫低平衡。"},
{"q":"关于身体状况不平衡，正确的有？","o":["有两种：出大于入和入大于出","在能量方面消耗＞摄入，这个人会比较瘦","在能量方面摄入＞消耗，身材肯定会发胖","出大于入和入大于出都属于高平衡"],"a":[0,1,2],"e":"身体状况不平衡也有两种：出大于入和入大于出。出大于入，即消耗＞摄入：在能量方面消耗＞摄入，这个人会比较瘦。入大于出，即摄入＞消耗：在能量方面摄入＞消耗，身材肯定会发胖。"},
{"q":"关于营养素方面的出大于入，正确的有？","o":["消耗＞摄入","长此以往，体内的营养素亏空","各种疾病也会随之而来","体重一定会发胖"],"a":[0,1,2],"e":"在营养素方面消耗＞摄入，长此以往，体内的营养素亏空，各种疾病也会随之而来。"},
{"q":"关于营养素方面的入大于出，正确的有？","o":["摄入＞消耗","要看是哪种营养素，以什么方式，摄入时间的长短等","症状的表现形式也会不一样","症状表现完全相同，与营养素种类无关"],"a":[0,1,2],"e":"在营养素方面摄入＞消耗，这就要看是哪种营养素了，以什么方式，摄入时间的长短等，症状的表现形式也会不一样。"},
{"q":"关于吃肉多了吃不下，正确的有？","o":["吃不下了，这是人与生俱来的自我调节能力","孩子一出生就有这个自主反射能力，吃奶吃饱了就会立即停止吃奶","是胃里的胃蛋白酶已经饱和，不能再分解蛋白质","肠道的脂肪酶和胆汁饱和，不能再分解脂肪","人的食量完全是主观意愿决定的"],"a":[0,1,2,3],"e":"是呀，吃不下了，这是人与生俱来的自我调节能力。孩子一出生就有这个自主反射能力，吃奶吃饱了，孩子就会立即停止吃奶，安安静静地去睡觉。……当肉吃多了，吃不下的时候，是因为胃里的胃蛋白酶已经饱和，不能再分解蛋白质；肠道的脂肪酶和胆汁饱和，不能再分解脂肪。"},
{"q":"关于人体保持总平衡的过程，正确的有？","o":["今天吃顶了，后面几天自然会多吃蔬菜、水果和粮食","又过了几天，胃肠道产生了新的蛋白酶和脂肪酶，又想吃肉了","这样身体才能一直保持总平衡","吃肉吃顶了以后应继续大量吃肉"],"a":[0,1,2],"e":"此时你的感觉是今天吃顶了，于是后面几天自然会多吃蔬菜、水果和粮食。又过了几天，胃肠道产生了新的蛋白酶和脂肪酶，又想吃肉了，于是就可以继续吃肉类，这样身体才能一直保持总平衡。"},
{"q":"关于孩子喊着要吃肉、要吃鸡蛋，正确的有？","o":["如果吃得比大人多，而且消化得了，还不积食，人也不胖","说明这段时间他的需求量大，他的消化酶也足够","说明孩子生病了","必须严格控制，不能让他吃"],"a":[0,1],"e":"如果一个孩子喊着要吃肉、要吃鸡蛋，吃得比大人多，而且消化得了，还不积食，人也不胖，说明这段时间他的需求量大，他的消化酶也足够。"},
{"q":"关于夏天的食欲变化，正确的有？","o":["夏天大家都特别想吃西瓜，因为身体在说“我需要”","夏天吃羊肉、牛肉少，也是身体在说“我消化不了，秋天再吃吧”","许多人不敢吃这个、不敢吃那个，是主观意识控制了人体的自主反射","身体拥有自己的智慧","夏天的食欲变化完全没有生理依据"],"a":[0,1,2,3],"e":"夏天，大家都特别想吃西瓜，为什么？因为身体在说：“我需要。”夏天吃羊肉、牛肉少，也是身体在说：“我消化不了，秋天再吃吧。”许多人不敢吃这个，不敢吃那个，不是不想吃，是不敢吃，是主观意识控制了人体的自主反射，却忘记了身体拥有自己的智慧。"},
{"q":"关于肠道黏膜的营养素调节功能，正确的有？","o":["肠道黏膜铺展开来面积可达200～400平方米","专门负责筛选可以吸收的营养素","能自己判断血液里缺哪种营养素，缺得多的就多吸收，缺得少的就少吸收","各种营养素在不同人不同时期之间的吸收率能差很多倍","肠道黏膜的面积只有2～4平方米"],"a":[0,1,2,3],"e":"肠道黏膜有个特殊功能，叫作营养素的调节功能。肠道黏膜铺展开来面积可达200～400平方米，专门负责筛选可以吸收的营养素。同时它还能自己判断血液里缺哪种营养素，缺得多的就多吸收，缺得少的就少吸收，因此各种营养素在不同人不同时期之间的吸收率能差很多倍。"},
{"q":"身体告诉我们吃多了的信号，正确的有？","o":["血糖高了，说明碳水化合物吃多了","尿酸高，说明含嘌呤的食物吃多了","血压高可就不一定，它的影响因素太多了","血糖高说明蛋白质吃多了"],"a":[0,1,2],"e":"还有一些信号会告诉我们吃多了：血糖高了，说明碳水化合物吃多了；尿酸高，说明含嘌呤的食物吃多了；血压高可就不一定，它的影响因素太多了。"},
]
